	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                             
	"MOBILE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                           
	"JOB_NUMBER" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                       
	"EMAIL" NVARCHAR2(32),                                                                                                                                                                                            
	"UNION_ID" NVARCHAR2(256),                                                                                                                                                                                        
	"IS_LEAVE" NUMBER DEFAULT 0,                                                                                                                                                                                      
